/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20211203-19","meetingId":"r03-cm12","date":"2021年12月3日","dateIso":"2021-12-03","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午前１１時５２分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"避難計画に関して、主としてマンションについての取扱いといいますか、位置づけについてお伺いしたいと思います。マンション管理組合というものが、私自身マンションに住んで４０年近く、ずっと理事をやっているのですけれども、その経験に基づきながら、どうなっているのかなということでお伺いします。では、マンション内での防災はどうなっているかというと、管理組合が独自に考えている。","respondent":"山本防災課長","answer":"その辺りの地域連携というところでは、管理組合は非常に大きな役割を果たしていると考えていますので、今後、どう連携を図っていくかというところは、区としても検討していきたいと考えています。","voiceIndex":6,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"防災アドバイザーの派遣ということですけれども、具体的にはどのように行っているのですか。管理組合のほうから申し込んでということなのでしょうか。それから、もう一つ。実態として、これまでどのぐらい派遣できたのか。何％ぐらいといいますか、大ざっぱでいいのですが、お分かりになるのでしたら教えていただきたい。","respondent":"山本防災課長","answer":"マンション防災アドバイザーにつきましては、管理組合のほうからご相談いただいて、いろいろ事前検討等も行いながら、実際に人を派遣するという運用を行っているところです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"今、お伺いした数字は、品川区内に存在するマンションの全体からすると、非常に少ないです。うちのマンションもそろそろ４０年近くになりますから、いろいろ地震の心配や水害の心配が出てきているところですから、品川区としても、そのようなマンションはたくさんあるので、かなり問題として自覚されているところだと思うのです。","respondent":"山本防災課長","answer":"管理組合への対応です。先ほど、支援や訓練等の件数を申し上げましたが、確かに区として全て把握しているわけではなく、もちろん管理組合独自で訓練されているところもたくさんあるということも認識しているところです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"今もちらっとご答弁の中に出ましたけれど、品川区もこのような手引を過去に作られているのです。これは平成２５年のものです。内容もしっかりしたものだと思います。せっかくこの手引があるのですけれども、建設委員会で配付されたときの資料を見ますと、この冊子になっている手引を２００部作って、ハンドブックは５００部作ったとあるのです。これは、管理組合のほうに配付されたのですか。どうでしょう。","respondent":"山本防災課長","answer":"ハンドブック等の配付方法につきましては、平成２６年度に配付しておりまして、管理組合向けの手引きについては、４９２部配付しておりまして、こちらにつきましては、区内にある１０階以上の高層マンションの管理組合に配付しています。","voiceIndex":12,"id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"それですら、助かる感じがあるのです。ですから、このように充実したもの、あるいはこれをさらにバージョンアップしていただくと、管理組合としては非常に助かるのです。ですから、ぜひそういう方向で、区から積極的に働きかけていただくような方向でやっていただきたいと思うのです。そこら辺どうでしょうか。そのようなこともお考えでしょうか。いかがでしょう。","respondent":"山本防災課長","answer":"その辺りを広く普及しながら、それぞれのマンションに対する特有の課題等もあるかと思いますので、そういった部分に対応できるよう、区としても働きかけというところをしっかり考えていきたいと思ってあります。","voiceIndex":14,"id":"exchange-005"},{"speaker":"おくの委員","kind":"質問","question":"これは高層マンションで、１０階以上ということになっているのですけれども、実は私の住んでいるところは７階建てなのです。そこら辺、町会・自治会との関連で、区がダイレクトにというところのお考えはいかがでしょうか。そこも少しお伺いしておきたいです。","respondent":"山本防災課長","answer":"町会を通しての働きかけという部分では、地域の連携強化に資する部分がかなり大きいと考えていますので、その辺りをどうしていくかというところを、今後のマンション対策も含めて、全般として考えていきたいと思っています。","voiceIndex":16,"id":"exchange-006","title":"町会・自治会支援"},{"speaker":"おくの委員","kind":"質問・要望","question":"マンションにはマンション独自の問題というか、特徴があります。それから、町会・自治会もやるだけで大変という、負担の重さがあると思いますので、もちろん町会・自治会とマンションが一体になってという側面もあるのですけれども、必ずしも町会・自治会を通さない道、ルートも排除しないようにしながらやっていただきたいと思います。そういうことを要望、意見として申し上げて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問","question":"それぞれの説明、ありがとうあります。これをどのようにやっていくのか。それと、アプリやネットといったものを活用した訓練というのが、私は今後の課題ではないかなと考えていますので、そういったことを行政はどのように考えているのかというのと、先ほど、１５ページに振り返りがありましたけれども、これは町会で行うのか、行政にやっていただくのか、そこら辺を教えてください。","respondent":"五十嵐災害対策担当課長","answer":"実施した町会のほうも非常にいいということなので、そういったものも含めて進めていきたい。それで、マンネリ化の防止を進めていきたいなと考えています。１５ページにありました防災訓練の振り返りについては、基本的には自治会の皆様が主体となってやっていただきたい。","voiceIndex":20,"id":"exchange-008"},{"speaker":"松澤委員","kind":"質問","question":"確かにマンネリ化した防災訓練に関しては、ＩＣＴの活用、このようなゲームというのは本当に大切だと思っています。少し所管が違うのですけれども、私は学校防災で子どもたちを巻き込むと、それに付随する保護者も一緒に学ぶという機会が増えますので、何とか教育委員会と手を取って、そういうものも１つなのかなと個人的に思っております。そこら辺だけ教えてください。","respondent":"五十嵐災害対策担当課長","answer":"今回、１２月４日の区内一斉防災訓練では、試行的に防災タブレットを活用して、区の災害対策本部と区内、３消防署、４警察と通信連携を図っていきたいなと考えています。その訓練結果を基に検証させていただいた上で進めさせていただきたいなと考えています。","voiceIndex":22,"id":"exchange-009"},{"speaker":"松澤委員","kind":"質問・要望","question":"備蓄に関してです。なぜなら、避難所というのは女性も使いますし、やはり女性の視点での配慮というのは大事だと思いますので、そこら辺がどうなっているのか教えていただきたい。これは、非常にすばらしい取組みだと思ったので、逆にこういう備蓄米を使ったレシピコンテストやレシピを配布する、または動画で配信するといった工夫があってもいいかなと思うのですけれども、そこら辺どうでしょうか。","respondent":"平原防災体制整備担当課長","answer":"区でもこういったところと合わせて、こういったところにこのような映像がありますとか、このようなレシピがありますということは啓発させていただきまして、備蓄物資の使い方が広く行き渡るように啓発してまいりたいと考えています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、松澤委員からもご質問がありましたけれども、同じことを伺おうと思っていました。見解を伺います。備蓄のほうから先に言ってしまったので、備蓄を伺いますけれども、備蓄物資の有効活用を考えておられて、本当に適切な対応だと思います。例えば、カセットコンロなどは、そういうものがなくて大丈夫なのでしょうか。先に備蓄だけ伺っていいですか。","respondent":"平原防災体制整備担当課長","answer":"先ほど、生理用品の配り方のお話がございましたけれども、そういった認識を、各避難所単位、あるいは私ども行政でも当然持っておりまして、起こってほしくはございませんが、次の災害が発生したときには、そういったことを繰り返さないようにしていきたいと考えています。","voiceIndex":27,"id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"それぞれ配慮されているということですので、ぜひそれを本当に実際の場で有効に機能するように検討していただきたいと思います。使用推奨期限がはっきりしないものについての扱いもよく分かりました。そうしたら、廃棄しなければいけないものの扱いがどうなのか教えてください。捨てるものはないと思うのですけれども、その辺はどうなのでしょうか。教えてください。","respondent":"平原防災体制整備担当課長","answer":"例えば、今お話のございました毛布について、毛布も当然廃棄という形ではなく、資源品として、また再利用できるという道もありますので、そういったところで活用しながら、決して廃棄して新しいものを購入することのないように、今、実際に運用させていただいているところです。","voiceIndex":29,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"このＡ３の資料でも、最後に区民向け訓練・啓発の課題と、職員向け訓練の課題が、それぞれ項目ではなるほどと思うのですけれども、例えば、これも課題を抽出しただけでは意味がなくて、今後、どうやってこれを解消していくのか、解決していくかの議論がされていると思うのですけれども、その議論の様子を、今、教えていただける範囲で教えていただきたいと思いますが、いかがでしょう。","respondent":"五十嵐災害対策担当課長","answer":"それと、職員向けの訓練につきまして、全庁的に災害対応可能な態勢の構築という部分では、１２月４日の震災図上訓練で、職員を約１５０名から２００名にボアアップさせて訓練に対応させています。","voiceIndex":31,"id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。区民向けのほうでも、ＩＣＴを活用した訓練となると、その前の幅広い世代に対する訓練。やはり参加していただかないといけなくて、若い世代が、このようなことであれば自分たちも協力できるというふうになるのではないかなと考えながら伺っていました。ぜひ、区として、それぞれアドバイスなどをしていただければと思います。これは要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-014","title":"町会・自治会支援"},{"speaker":"たけうち委員","kind":"質問","question":"そのときに、よく町会長などから出るのは、同じ品川区の中でも、隣の町会の人が来たみたいな、今は少なくなったと思うのですけれども、そういう面でいくと、区を越えて、区境の中で、そういう近隣区との連携というのですか。その中で、２・３日目が都、その後が国となっていて、実際問題、このとおりいけばいいのですが、都から来るものが１日遅れたときにどうなのかなという心配をしてしまうのです。","respondent":"五十嵐災害対策担当課長、平原防災体制整備担当課長","answer":"区境の町会の連携ということですけれども、その点については、どうしても町会の方は自分の町会のことを一番に考えてしまいますので、どのように連携していくかということは、これから研究していきたいなと考えています。先ほど、ここでご紹介させていただきました災害救助法の考え方の１つに、現在地救助の原則というものがあります。困っている人がいたら、その場で手当てをせよというものです。","voiceIndex":35,"id":"exchange-015","title":"町会・自治会支援"},{"speaker":"たけうち委員","kind":"質問・要望","question":"浸水関係の防災訓練もやり始めたということで、コロナでできませんでしたが、やはりこちらも大事なので、またしっかり取組みを進めていただきたいと思います。お互いさまですので、そこのところはぜひご理解していただくように日頃からお願いしたいと思います。備蓄については、分かりました。そのためには、何をどうしておくのか。その辺は、何か工夫されていますでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"もちろん、生活環境に応じて対応してほしいということも、加えてお伝えしています。しながわ防災学校のほうでも、個別に家具の転倒防止や、しながわ防災体験館のほうでも、また個別にご指導していますので、そういったところをご活用いただければと考えています。","voiceIndex":38,"id":"exchange-016"},{"speaker":"たけうち委員","kind":"質問・要望","question":"これは、一応要望というか、今後の考え方として、非常に難しいかもしれないですけれど、例えば、こういう時期ですから、高齢者のお宅に上がるかどうかは分かりませんけれども、民生委員の方、また、介護ヘルパー、ケアマネジャーの方も、知識として、独り暮らしの高齢者が住んでいらっしゃるお部屋では、ここにこういうものがあると危ないなという意識を持っていただいて。","respondent":"滝澤災害対策担当部長","answer":"もしくは、２階に上がれば命は助かるだろうということで、セカンドベストの逃げ方という訓練であれば、多分かなり広い範囲で参加をしていただけるのです。個別計画の作成と合わせて、逐次、防災訓練のやり方についても、地域とともに連携しながら考えていきたいと考えています。","voiceIndex":40,"id":"exchange-017"},{"speaker":"こんの委員","kind":"質問","question":"何点かあります。そこら辺、備蓄に対して、こうした方々が、もっと向上させて、自分たちで自分たちの命を守るというところへ、何か区として後押し、あるいはそうした考え方をされている方たちへのさらなる支援をしながら、公助を入れながら、自助を高めていくという取組みはされているでしょうか。これは、硬いパンのことでよろしいのでしょうか。その２点をお願いします。","respondent":"山本防災課長、平原防災体制整備担当課長","answer":"マンションへの助成支援についてのお尋ねです。区としましては、まず、マンション防災については、各居住者の自助、それから、居住者同士の共助で対応するのが原則だと考えています。私からは、備蓄品のうち、ビスケットの取扱いにつきまして、お答えします。ビスケットですけれども、以前、防災備蓄品では、広く乾パンというものが入っていた時代があります。","voiceIndex":43,"id":"exchange-018"},{"speaker":"こんの委員","kind":"質問・要望","question":"具体的には、女性などが入ってくると、もっと意識を高められて、１棟、いわゆるご自分たちが住んでいるところだけで、マンション避難所という形にできる。要望で終わります。いわゆる高齢者が食べられれば、皆様全員食べられるぐらいのものだと思うので、そこに費用をかけるよりも、もっと効果的な備蓄、ビスケットは変えたほうがいいのではないかと思うのですが、その点、もう一回、いかがでしょうか。","respondent":"平原防災体制整備担当課長、山本防災課長","answer":"ビスケットは、先ほどの繰り返しになりますが、確かに非常に硬い。果たして、あの１つが本当に１食なのかという問題はありますけれども、まだ、私どもも、いろいろ研究は進めてあります。計画等は以前もあったところですので、今後、そういった訓練等も行いながら、その成果は、各避難所にもフィードバックしながら、ペットの同行避難の受入れに対して、全避難所で理解が得られるよう。","voiceIndex":46,"id":"exchange-019"},{"speaker":"こんの委員","kind":"質問・要望","question":"ビスケットの件。いろいろなメリット、デメリットがあるのだろうなというところですけれども、いろいろな備蓄の食品が出てきていると思いますので、研究をしていただきたいと思います。ペットの同行避難は分かりました。３４か所で受入体制が整ってきたというところで、なかなかこの受入れの体制をとるというのは難しい。その課題の点が１つ。その辺の状況を教えてください。","respondent":"山本防災課長","answer":"１点目のマニュアル化されていないところの課題ですが、避難所の考え方にもよるのですけれども、やはりどうしても、まず人を優先にいろいろ考えていきたいというところで、ペットの受入れの部分の検討まで進んでいないというところが、一部あると認識しています。","voiceIndex":49,"id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"全部の避難所で同行避難ができる体制が望ましいと思うので、この辺、何が課題かというのを、いま一度整理しながら進めていただきたいというところです。訓練についても、これは計画を立てたところから、やはり１度は実施して、まずは図上訓練からやってみるとか、イメージを持って、同行してきたペットをどこにどのようにゲージを置いて、どうするのか。何かございましたら、お答えください。","respondent":"山本防災課長","answer":"その辺りは、生活衛生課とも連携をとりながら、周知等を図っていきたいと思ってあります。","voiceIndex":51,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今日、しながわ防災訓練ガイドの配付をしていただきありがとうございました。これには、訓練のメニューがいろいろと紹介されていたり、本当に参考になるところがたくさんあるなと思って見させていただきました。その点を少しお聞かせいただきたいと思います。具体的に、この防災訓練ガイドは、どういうところで、どう活用されているのか。その点について、教えてください。","respondent":"山本防災課長、五十嵐災害対策担当課長","answer":"被害想定の件について、私からお答えいたします。しながわ防災訓練ガイドにつきましては、各自治会で単独訓練を実施する場合、もしくは地区防災訓練でこのような訓練をやりたいというときの参考資料として活用いただいております。","voiceIndex":53,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、消火器も、いっとき町会の中でかなり増やしていただいたと思うのですけれども、消火器もどこにあるかというところで、消火器ラリーという、町会みんなで場所を確認して、いざというときにはここにあるよということでみんなで持ち寄るという訓練をされているところがあると思うのですけれども、消火の訓練についての品川区の考え方を教えていただきたいと思います。","respondent":"山本防災課長、五十嵐災害対策担当課長","answer":"私から、被害想定の最初の質問について、お答えいたします。要は、初期消火体制のお話かと思います。それについては、今後、消防署、消防団と連携して、区としてもしっかりした初期消火、防災行動力を高めていく方法をしっかり伝えていきたいと考えています。","voiceIndex":56,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"木密のところの火災危険度というのは、ずっと指摘されてきているところだと思います。そこの差をなくしていこう、区民消火隊や、ミニポンプ隊がしっかりと機能するような形でやっていこうということで、地域、町会なりに働きかけをして、そういう配備もしていこうという考えなのか、その点は町会によって配備の状況がかなり違うので、どう考えられているのかについても伺いたいと思います。","respondent":"山本防災課長、五十嵐災害対策担当課長","answer":"場合によっては、町会によって隊を２つ結成していれば２台配備している。そういった考え方で伺っているところです。可搬ポンプの取扱いについて、お答えします。それにつきましては、基本的に区民消火隊の方々は、地域の消防団の方と連携して取扱いについて学び、訓練をされているのが実情です。","voiceIndex":59,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう配備というのは、このように配備していきたいとか、このように区民消火隊、ミニポンプ隊を作っていきたいとか、そういう区としての考えは何かあるのか、伺いたいと思います。","respondent":"山本防災課長","answer":"初期消火についてのお尋ねです。先ほど申し上げたとおり、消火ポンプにつきましては、区民消火隊、それから、ミニポンプ隊を結成している部分に配備しているところで、そういった隊がない町会もあると認識はしています。","voiceIndex":62,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここでも何回か申し上げたのですけれども、そういう点では、区としても積極的に、防災公園が１つもなくて、訓練する場所も、また、集まる場所も町会としてないというところを早急に解消するような手立て、ぜひ防災公園を意識的に造るという取組みを区としてもしていただきたいと思うのです。もう一度、その点について伺いたいと思います。","respondent":"藤田防災まちづくり部長","answer":"しかしながら、なかなか適地が見つからないという現状もありますので、私どもも探しますし、地域の方々から、あそこにいい土地があるよというお話があれば、そういう声を頂きながら、積極的に進めていきたいと考えています。","voiceIndex":64,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"備蓄ですけれども、先ほど、区民避難所のところで、ワンタッチ型の間仕切りですか、それもコロナ対策で配備したというご説明だったかと思います。ここから学校の避難所まで持っていくというのは、現実、すごく大変になると思うのです。そこら辺のところで、必要数、どんなものが、どれくらい配備されているのか、伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"考え方としましては、当初のご説明のとおりですけれども、すぐに必要となるものは、原則学校に入れるという考えの下でやってありますが、一方で、スペースの関係を考えながら進めているところです。","voiceIndex":66,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"なぜ１,２００セットなのかということも教えてください。あのようなところには、簡易間仕切りなども置けるということになっていくのでしょうか。例えば、学校と接したところに空き家が出たりするようなことがあれば、区としても積極的にその土地を購入して、備蓄倉庫として活用する方針というか、考え方があるのか、その点についても伺います。","respondent":"平原防災体制整備担当課長","answer":"当時、令和元年の台風１９号で、区内の最大の避難者が５８４名ということでございました。それで、必要数は、その２倍の数に対応できるようにということで、１,２００セットを用意させていただいてあります。","voiceIndex":68,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"間仕切りというのは、風水害だけではなく、地震の避難のときも必ず必要になってくると思います。今、テレビなどで放映されている避難所でも、かなり間仕切りやテントが進んできているなという思いがしています。品川区として、ぜひ震災の対応としても、間仕切りというのはしっかりと備蓄をするようにお願いをしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-029"},{"speaker":"湯澤委員","kind":"質問","question":"私からは、職員向けの訓練について、少しお尋ねしたいです。様々な訓練があることが分かりましたけれども、その際に、やはりコロナ禍で区民向けの訓練は思うようにできなかったわけですけれども、職員向けの訓練がどうであったのか。縮小したり、個別訓練等を行ったりしたのかを教えていただければと思います。","respondent":"五十嵐災害対策担当課長、滝澤災害対策担当部長","answer":"職員向けの訓練がコロナ禍でどうだったのかというご質問ですけれども、縮小はしておりません。ソーシャルディスタンスをとりながら訓練を実施しております。これは、先ほどありましたように、課題を克服するために訓練しなければいけないのですけれども、必要性と可能性がありまして、今、そこを探りながらも実施をしているという状況です。","voiceIndex":72,"id":"exchange-030"},{"speaker":"湯澤委員","kind":"質問","question":"大変力強いご答弁、ありがとうあります。新しい取組みや、新しい備蓄品の使用方法といったところがあるかと思います。今、スマートフォン用の蓄電池のお話をしましたけれども、例えば、そこに簡単なマニュアルみたいなものがあれば、誰もが分かるのかなと思うのですけれども、そういった取組みをされているのかも教えていただければと思います。","respondent":"平原防災体制整備担当課長","answer":"今後とも、そういった新たに入るものにつきましては、確実に周知、広報するとともに、使い方についての訓練を続けていきたいと考えています。","voiceIndex":75,"id":"exchange-031"},{"speaker":"湯澤委員","kind":"質問・要望","question":"備蓄物資の輸送手段についても少しお尋ねしたいです。この輸送手段は、こちらを読ませていただくと、トラックなのかなと思います。例えば、災害が起きてしまって、道路の状況が大変悪くなってしまって、トラックなのか、車が避難所まで行くことができないといった場合には、まさに共助によって、避難所にいる区民の方が協力して物資を運ぶという計画なのか、それを教えていただきたいと思います。","respondent":"平原防災体制整備担当課長","answer":"共助でして頂くのは、避難所まで行ったところの荷下ろし作業と配付作業をお願いしようと考えています。","voiceIndex":77,"id":"exchange-032"},{"speaker":"湯澤委員","kind":"質問・要望","question":"分かりました。ただ、いざ災害が起きると、やはり区民の方もパニックを起こしてしまうと思いますので、先ほど、松澤委員からもお話がありましたけれども、いざというときに職員の方に先導していただけると、区民も落ち着いて共助が行いやすいのかなと思いますので、区職員向けの訓練を大変充実してやられているということなので、引き続き行っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-033","title":"町会・自治会支援"},{"speaker":"小芝委員","kind":"質問","question":"端的にお聞きします。別紙の２の８ページ、生活用水の給水に係る計画のところです。こちらは、生活用水というところで、飲料用水ではない。飲料用水の場合は、１日、１人当たり３リットルを基本とされているということです。この生活用水、例えば、西大井広場が２５０立方メートルということだと、大体何人ぐらいの方を対象に、均一にどのぐらいの量を供給する予定なのか教えてください。","respondent":"平原防災体制整備担当課長","answer":"飲料水の提供ですけれども、災害時の飲料水につきましては、ペットボトルだけで全て対応するということではなく、こういった震災対策用の井戸や、各学校についております、災害時の給水の遮断弁といったものを活用して水を確保しています。","voiceIndex":81,"id":"exchange-034"},{"speaker":"小芝委員","kind":"質問","question":"地域によっては、これまでも予算特別委員会等でも質問させていただきましたけれども、私有地の中に井戸のある家庭もありますので、そういったところの整備も、ふだんから使っているご家庭であれば、こういう緊急時でも使えるのでしょうけれども、ふだんなかなか使っていないよという方もいらっしゃると思いますので、そういったところへも支援などをお願いしたいなと思うのですけれども、お考えがあれば。","respondent":"平原防災体制整備担当課長","answer":"一方で、生活用水を含めた広くお水という形になると、どのような形で必要になるかというのは、当然水があるにこしたことはないということもありますので、今後とも、災害時における水の全体像をいろいろ勘案しながら、今。","voiceIndex":83,"id":"exchange-035"},{"speaker":"大沢副委員長","kind":"確認","question":"とりわけ高齢者の方、女性の方、そして、子どもたち、そこの運用指針というか、国では内閣府等々で、都も出しております。品川区独自のものがあるのか、それに準拠した運用指針なるものがあるのか、そこのところだけ確認させてください。","respondent":"平原防災体制整備担当課長","answer":"災害時のトイレですけれども、ご指摘のとおり、国等々からは指針が出ているところです。品川区におきましては、各避難所連絡会議単位で、こういったものがありますというご紹介の段階にとどまっておりまして、例えば、どのような順番でという指針までは至っていない現状です。","voiceIndex":86,"id":"exchange-036"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"各避難所に任せてあるということですが、やはり行政がある程度一定の手を差し伸べないことには、うまく機能して動いていかないようなことが私は予想されますので、避難所に任せるのもいいですけれど、先ほど、小芝委員が水を出すほうが一番大事で、これは環境、あるいは健康にも及ぶものですので、そこのところはなるべく留意をする、あるいはそこに力点を置きながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6606#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":35735,"voices":94}},{"id":"r03-20211208-10","meetingId":"r03-cm12","date":"2021年12月8日","dateIso":"2021-12-08","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和３年第４回定例会","agenda":"令和３年第４回定例会","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"第６６号議案品川区立児童センター条例の一部を改正する条例の採決について、この場をお借りしておわびと説明をさせていただきたいと思います。この６６号議案は、児童センターの老朽化に伴う改修工事にあたってというもので、本来、文教委員会で賛成すべきところ、誤って反対してしまいました。共産党としては、６６号議案については賛成させていただきたいと思います。大変申し訳ございませんでした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-001"}]},{"id":"topic-02","title":"東京都後期高齢者医療広域連合議会の報告","agenda":"東京都後期高齢者医療広域連合議会の報告","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"厚生委員会と重なってしまって欠席というところはやむを得ないと思います。一言、後期高齢者医療広域連合議会におきまして、来年度の保険料の値上げが報告されていると思います。共産党としては、苦しい生活の中、これだけコロナ禍の下、住民負担が重くなっている中、保険料引上げは行うべきではないと、意見だけ述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5434#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":9184,"voices":28}},{"id":"r03-20211209-9","meetingId":"r03-cm12","date":"2021年12月9日","dateIso":"2021-12-09","committee":"文教委員会","time":"午前１０時４８分～午前１１時４２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第８８号議案 令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第８８号議案 令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料には、児童手当支給対象となる児童が対象となっておりますが、所得制限はあるのでしょうか。その中身について伺いたいと思います。先行給付は今回１５歳までですよね。児童手当対象となる方が先行ということなのですけれども、残りの１６歳以上１８歳以下の子どもには、いつどのように支給する考えなのか、伺いたいと思います。","respondent":"伊東子育て応援課長","answer":"１６歳から１８歳までに関しましては、申請が必要になるという話をしたところですけれども、年明けというか来年から作業に入るという予定です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回、補正予算を組んで、なぜ子育て世帯のみの給付でとどめるのでしょうか。伺いたいと思います。私はやはり、補正予算を組むのであれば、これまでも求めてまいりましたけれども、大学生を抱える困窮世帯や、あるいは若者単身世帯への臨時支援金というのも、区独自に支給すべきではないかと思いますけれども、いかがでしょうか。","respondent":"伊東子育て応援課長","answer":"今回、子育て世帯への臨時特別給付ということで、国がそういう方針を決めまして、我々はそれに基づいて粛々と進めていくです。それ以外の部分でというお話がございましたけれども、これ以外に国では様々な形で同時に支援策を考えているという状況にあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"２点目ですが、コールセンターの運営等委託経費１,０００万円なのですけれども、これはどこに委託するのか伺いたいです。３点目は、保護者のニーズあるいは支払いの迅速性や、あるいはクーポンにすると様々経費がかかるという報道、指摘もありますけれども、経費節減の観点からも、品川区も１０万円を現金で支給すべきなのではないかと思うのですけれども、いかがでしょうか。","respondent":"伊東子育て応援課長","answer":"後段というか、今回は先行給付ということで、５万円分現金支給ということで作業を進めているわけですけれども、後半のクーポンか現金かという話が今、出ているところですけれども、具体的に国から、まだ正式な形が示されておりませんので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"示されていないということですが、先ほど紹介したように、自治体によっては、需要に応じて、現金でも可能とするということを言っているわけですから、これは自治体として、品川区として、先ほど、そういった声もあることは承知しているということでしたけれども、私は現金で払うべきだと考えていますので、できれば今回一括して１０万円というのが、そのほうが早いですから一番よかったのですけれども、ただ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"これも報道の範囲ですけれども、選択は自治体の判断に任されているという報道と、そうではあるけれども、近隣にクーポンが使えるような商業施設がないところに限ってほしいというような、どっちとも取れるような報道なのです。それで、具体的に国から、こうするようにと示されたときには、それにそのまま従ってしまうということなのでしょうか。その辺についてお考えを伺いたいと思います。","respondent":"伊東子育て応援課長","answer":"ですので、それを見た上で、どうするかというのは考えていかなくてはいけないのかと。まだ今のところ、はっきりとしたものは示されていないという状況で、何ともお答えできないかという感じです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"子育て施策に資するクーポンというのは一体何なのだろうと思います。学用品や、もちろん教育に関わるところなどもあると思うのですけれども、原則的に子育てに有効なことに使うクーポンというのが、それ自体、かなりいろいろな判断を迫られると思いますので、国から示されるとしても、ぜひ区としての判断もそこに加味していただきたいと思うのですが、その辺についてもう一回、お考えを伺いたいと思います。","respondent":"伊東子育て応援課長","answer":"それを見て、品川区としてどう考えていくかというのは、当然判断していかなくてはいけないと思います。全体像を見た中で、子育てに限定したクーポン券がいいのか、現金がいいのかというのは、もう少し具体的なことを見ないと判断できないのかと思っているところです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり、子育てに資するためのというのも、子育てというのはかなり広範囲になりますので、ぜひその辺は、生活者ネットワークとしては現金での給付ということを、いろいろな区としての経費削減の意味もありますし、実際に子育てをしておられる方のニーズにも一番それが合うのではないかと思いますので、そのように検討していただきたいということ、これは要望でとどめます。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"今、ちょうどご説明があったのですけれども、すごくそこは大事なところだと思うので伺いたいのですけれども、今の地域の実情に合わせてというところがありました。当区としては、そこが今できないのは、まだ政府から、実情に合わせてというところの詳しい内容が出てきていないからということでよろしいのでしょうか。","respondent":"伊東子育て応援課長","answer":"その後のことに関しては、時期が遅れて通知しますというような話があったところだったので、その時点で１０万円一括という話は全く考えていなかったところでございまして、今はまさに１２月のこのタイミングですので、今は５万円の先行給付に集中している状況です。","voiceIndex":19,"id":"exchange-008"},{"speaker":"松本委員","kind":"質問","question":"今の通知というのは恐らく、２６日ということなので、さっきも出ました、内閣府政策統括官から来ている「令和３年度子育て世帯等臨時特別支援事業の実施について」という通知かと思います。それで、検討されなかった理由として、もう一度伺いますけれども、実情の部分というのが示されなかったからと理解してよろしいのでしょうか。","respondent":"伊東子育て応援課長","answer":"確かに、１１月２６日の段階の通知は、広い意味で子育て世帯の、後半の５万円の部分を含めた形の通知です。","voiceIndex":21,"id":"exchange-009"},{"speaker":"松本委員","kind":"質問","question":"これはまた、これからの議論ですごく重要になってくる点だと思うのですけれども、今回の先行の５万円、そして後々のクーポン券。もう一度、趣旨のところ、どのように政府から説明されているのか伺います。","respondent":"伊東子育て応援課長","answer":"もっと広く言えば、先ほどのクーポンの話に出てくるかと思うのですけれども、一応、先行給付に関しては、このようなことで進めさせていただいたです。","voiceIndex":23,"id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"クーポンのところも含めて、この通知を拝見しているのですが、ここも本当に大事なところだと思います。改めて、ここはきちんと、区としての見解を伺わないといけないのですけれども、あくまで子育ての支援であって、地域振興であるとか、そういったものは、この趣旨には含まれていないと理解してよろしいですか。","respondent":"伊東子育て応援課長","answer":"現に国で補正予算の審議がされていて、後段の５万円の部分、クーポンの部分に関しては、まさに今、審議中ということで、なかなか国の方針が決定していないということもありますので、もう少し通知を待たないといけないかです。","voiceIndex":25,"id":"exchange-011"},{"speaker":"松本委員","kind":"確認","question":"趣旨のところが長くなったのですが、その上で、もう少し具体的にお伺いしたいのがコールセンターですけれども、このコールセンターはいつからいつまで開設する予定でしょうか。","respondent":"伊東子育て応援課長","answer":"１２月中旬、通知するタイミングに合わせて開設しようと考えています。期限につきましては、取りあえず現状で、年度末までに支給という話になってありますので、そこで一旦の契約をしようかと考えておるところです。","voiceIndex":27,"id":"exchange-012"},{"speaker":"松本委員","kind":"質問","question":"その契約の中には、今後追加で出てくるクーポンですけれども、このクーポンについての問合せも契約の中に含まれていると考えていいのでしょうか。","respondent":"伊東子育て応援課長","answer":"大きな意味で、先ほど委員がおっしゃった１０万円支給という部分の事業ですので、当然そこの部分、そのとき決まっているかどうかという部分はありますけれども、問合せには対応するという契約をしようと考えています。","voiceIndex":29,"id":"exchange-013"},{"speaker":"松本委員","kind":"質問","question":"そうすると、年内に５万円給付して、年度末に間に合うかはまた別論ですけれども、年度末までにクーポンもしくはその他の手段で交付するというふうになった場合の問合せ、この後段のほうの追加について、業務の内容としてコールセンターに入っていったとしても、予算額としては変わらないと考えていいのでしょうか。","respondent":"伊東子育て応援課長","answer":"今、３月３１日と言ったのは、先行給付分の部分での一定のめどが立つということで、当初の契約はそういうふうにしようと思っているところです。ですので、今後の展開によっては、契約延長や契約変更など、様々別のことを考えていかなくてはいけないかと思っています。","voiceIndex":31,"id":"exchange-014"},{"speaker":"松本委員","kind":"確認","question":"ここの部分は今、確認できたかと思います。追加ですけれども、これは今回、５万円なのか１０万円なのかというところがありますけれども、今回は現金５万円をまずは振り込むです。これは、５万円振り込むのか１０万円振り込むのかで、振込手数料というのは変わるのでしょうか。","respondent":"伊東子育て応援課長","answer":"金額だけでは、５万円、１０万円での金額で、単価の変更はなかったと考えていますので、当然、振込のところだけ考えれば変わらないかと思っています。","voiceIndex":33,"id":"exchange-015"},{"speaker":"松本委員","kind":"確認","question":"２回振り込むことになる。これは、クーポン券ではなくて現金でやる場合も、２回やる場合というのは、２回振込手数料がかかる。１回であれば１回分の振込手数料で終わるということも確認できたかと思います。この辺りの想定は今どうなっているのでしょうか。","respondent":"伊東子育て応援課長","answer":"国も、当初の概略というか案の中では、遅くとも６月ぐらいまでにはということが言われていたかと思うのですけれども、なかなかクーポンというか、制度設計にもよるのですけれども、いろいろ大変、時間がかかるかと思っています。","voiceIndex":35,"id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"長くなったので、そろそろ終わりますけれども、おっしゃられたところで、本来は、当初はクーポンについては、卒業式や入学式や新学期というふうな話でしたけれども、今お伺いしたところでは、６月という話が政府から出ているということだと思います。","respondent":"伊東子育て応援課長","answer":"現状では、まだ正式に示されていないという中で、意見がどうのこうのという話にはなっていないところですけれども、都レベルで、どういう進捗ですか、検討を始めましたかみたいな話は、問合せが来ているところです。","voiceIndex":37,"id":"exchange-017"},{"speaker":"松本委員","kind":"質問・要望","question":"最後に要望ですけれども、以上伺ったところでも、やはり、ずるずると国の判断を待ってやるよりも、我々は年内に一括で１０万円やったほうが、これは当然、区民の方たちにとってもメリットがあると思うところですので、もう今日で採決というところですけれども、何とか年内に一括で１０万円できることを要望いたしまして、私は終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-018"},{"speaker":"松澤委員","kind":"質問・要望","question":"いろいろお話が出たので簡潔に、要望みたいな形で言わせていただきたいのですけれども、私も現金給付を希望しております。なぜなら、やはりクーポンという部分で事務のお金がかかる。何よりも大切なのが、迅速性なのです。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-019"},{"speaker":"つる委員","kind":"質問・要望","question":"今、各委員のご質疑を伺っていて理解したところもありますが、まず、そもそもの前提の数字をいろいろ、この際なので教えていただきたいと思うのです。そういう中で、今回の対象が児童手当支給対象というところで、まず今現在、品川区の児童手当の支給対象人数、今回の給付金の起点となるのは令和３年９月現在ですけれども、まず、令和３年９月現在の全部の児童手当が給付されている人数を教えてください。","respondent":"伊東子育て応援課長","answer":"区が把握しているというところでの児童手当、特例給付も含むというところで、人数的に言いますと、４万６,６７７人というのが、給付準備で拾った数字となっています。","voiceIndex":43,"id":"exchange-020"},{"speaker":"つる委員","kind":"質問・要望","question":"まとめて伺うと、９月現在では、今おっしゃっていただいた数字で、それ以降、年度内、来年の３月までに出生が予定されている人数、お子さんが出生されれば、当然、特例給付も含めた児童手当の対象になると思うのですが、そこの人数の想定というのは何人なのでしょうか。教えていただきたいと思います。それと併せて、先ほどご答弁いただいた４万６,６７７人の中での特例給付の人数を教えてください。","respondent":"伊東子育て応援課長","answer":"出生見込みですけれども、一応、昨年の同時期、１０月から３月３１日というところを見ますと、１,５００人程度いたというところで、一応、マックスではないですけれども、その人数、１,５００名を見込んだところです。","voiceIndex":45,"id":"exchange-021"},{"speaker":"つる委員","kind":"確認","question":"児童手当を受けていらっしゃる公務員の方は申請が必要で、先ほど冒頭のご説明では、１月の早い時期に、その方たちにも書類も送りますというふうになっているのですが、これは事前に確認できなかったので、そもそもの話だと思うのですけれども、児童手当というのは、どういう仕組みで、把握しないままできたという、先ほどのご説明の在り方だったのですけれども。","respondent":"伊東子育て応援課長","answer":"ですので、周知の仕方としては、結果的に申請いただくのですけれども、在勤庁から一斉に周知していただいて、各自治体に申請していただくという形になります。","voiceIndex":47,"id":"exchange-022"},{"speaker":"つる委員","kind":"確認","question":"分かりました。すみません。私は不勉強なので、在勤庁というのは、各省庁の「庁」ということですね。そうすると、地方公務員は品川区という理解でいいと理解しました。分かりました。では、ごめんなさい。確認で、お願いします。","respondent":"伊東子育て応援課長","answer":"勤め先、私が今、品川区役所に勤めていて、子どもがいるという形になれば、品川区役所から児童手当が、所得の関係で出ているという形になりますので、区や省庁、いろいろな公務員がいらっしゃいますけれども、所属しているところから手当が支給されているという形です。","voiceIndex":49,"id":"exchange-023"},{"speaker":"つる委員","kind":"確認","question":"繰り返しになりますが、公明党は、そもそも一律というところを、これは政党の公約なので、そこは最終、政府としてどうするかというのは、また別の話ですけれども、今回、区の対象となったものについても、そういう前提でいろいろ捉えていきたいというところがあるのですが、１点、先ほど松本委員の質疑の中でも、通知のところでの確認をしていただいたとは思うのですが、改めて。","respondent":"伊東子育て応援課長","answer":"今の、自治体の判断でというところに関しては、自治体でそれぞれ創意工夫して、実施に向けて準備しろというような通知は来ているところですけれども、その中で、やはり細かい部分での要領が示されていないので、いろいろと示された段階で質問したいというように考えております。","voiceIndex":51,"id":"exchange-024"},{"speaker":"つる委員","kind":"確認","question":"分かりました。そこはまた別の議論ですが。それで、まだ分からないけれど、残りの５万円相当のところになっていく。先ほど、クーポンについては６月などという可能性もという、国の話としてご答弁があったわけですけれども、ただ現金の５万円についてのタイミングというのは、国の補正予算の関係もあるのでしょうけれども、年度内に５万円というのは、いくことなのでしょうか。","respondent":"伊東子育て応援課長","answer":"仮の話ですけれども、対象者は同じなわけです。クーポンにする云々という後段の話も同じなわけですので、今、先行してやっている部分の対象者が確定すれば、２回目として、仮に現金で支給するとして、その人に対して支給するという形になりますので、時間的には年度内で。","voiceIndex":53,"id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"今回、議案でかかっている以外のところの部分なので、参考ということでお答えいただいたと思うのですが、それで、スケジュールのところで、今回の現金５万円は、１２月下旬で給付対象者に給付金支給とあるのですが、児童手当の振込などと同じ考えでいくと、これは今回挙げられている対象の３万３,４４６人に、同時に、一括という表現かどうか分からないですけれども、支給されるということでいいのですか。","respondent":"伊東子育て応援課長","answer":"対象の３万３,４４６人には、先ほどの、公務員や出生の部分が数字的には入っていますので、それは除かれて、まさに区からの児童手当をもらっている方に関しては、通知を差し上げて、間に辞退届の関係がありますので、それの受付をして。","voiceIndex":55,"id":"exchange-026"},{"speaker":"つる委員","kind":"提案","question":"分かりました。その上で、最後に、冒頭申し上げたとおり、今回の５万円プラス５万円相当というのは、そもそも公明党が提案申し上げて、国政の場で与党の中でもしっかりと協議されて今の制度になったという中で、今、様々な議論の中で、残りの後半の５万円についても、現金がいいというような世論の声も非常に大きいということもあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-027"},{"speaker":"安藤委員","kind":"意見","question":"賛成です。対象が少しまだ不十分な点や、様々改善すべき点はあると思いますけれども、今回の補正予算の中身は、コロナ禍の下での子育て支援に必要なものですので賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"先に少しだけ意見を述べします。生活者ネットワークは、子育て世帯への応援というのが現金給付でいいのだろうかという思いは実はあります。ですので、今後の子育て世帯への応援策についてはもう少し検討していただきたいと思いますが、これは国の方針でもありますので、この給付については賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-029"},{"speaker":"松本委員","kind":"質問・要望","question":"賛成です。それはもう、事務費を考えても、それが一番適切だと思います。そこは改めて要望したいところではありますが、本件については、やはり今日の各会派のご意見を伺っていても、政府の在り方というのはあまりにもひどいと思うところで、今回、大阪市をはじめ幾つかの自治体で年内に１０万円というところを言っている中で、政府で当初の発信を翻して、やはり基本はクーポンなのだという話をする。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5052#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":15934,"voices":69}},{"id":"r03-20211209-5","meetingId":"r03-cm12","date":"2021年12月9日","dateIso":"2021-12-09","committee":"総務委員会","time":"午前１１時５０分～午後 ０時１４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"説明に入る前に、所管委員会における審査結果","agenda":"説明に入る前に、所管委員会における審査結果","exchanges":[{"speaker":"おくの委員","kind":"提案","question":"苦しい生活・営業を救うためにも、政府の補助金だけに基づくのではなく、場合によっては、品川区自身も区民の営業や暮らしを考えて、財政出動することをためらうべきではないと私は思いますので、そういうことも念頭に置きつつ、品川区もクーポンではなく、５万円を現金で給付することを考えるべきではないかと思うのですけれども、その点いかがお考えでしょうか。この２点をお尋ねしたいと思います。","respondent":"黒田財政課長","answer":"残りの５万円のクーポンの件ですが、いわゆる５万円相当のクーポン給付事業につきましては、現在、国会で審議されておりまして、こちらは今回の５万円と違いまして、補正予算に計上して、ただいま国会で審議されている最中ということでございまして。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"報道も、盛んにそういう方向でされているということですので、そのような品川区民自身の望みを入れていってほしいと思います。それから、予備費の枠内の範囲だし、国で審議されている最中ということですが、品川区自身はどのようにお考えでしょうか。今の景気の状況、あるいは財政出動の必要性、今回の国の範囲では狭過ぎるのではないかということですけれども、どのようにお考えでしょうか。","respondent":"黒田財政課長","answer":"品川区として、そのほかの経済対策がどうなのだですが、これまでも様々、当初予算の編成でありますとか、年度途中の補正予算の編成の中で、事情に応じて対応しておりますし、事情に応じて対応するためには財源も必要となりますので、適宜対応していくというところでございまして。","voiceIndex":7,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"それに対応できるだけの財政出動あるいは経済対策を打っていただきたいと思います。それが政治・経済を預かる者の使命だと思いますので、どうぞよろしくお願いいたします。意見、要望ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"総合審査のことで、いつも生活者ネットワークとして意見を言わせていただいているのですけれども、文教委員会での議論の様子をぜひお知らせいただきたいと。今回の補正予算については、理事者のほうも席に戻られているというか、理事者の時間もあったと思うので、説明や意見、質問なども出ていたと思うので、そういうふうに委員会の運営をぜひ検討していただければというのを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"続けます。文教委員会の傍聴に行ったのですけれども、まず、歳出の中の、コールセンター運営等委託について、文教委員会でも質疑がありました。その中で気になったのが、コールセンター運営等委託がどのような契約になっているのかというところを伺いたいのですけれども……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"田中委員","kind":"意見","question":"それで、文教委員会の質疑の中でも、委託についての契約の中身というのが、きちんと答弁されていなくて、随意なのかプロポーザルなのか。それで、これからすぐにコールセンターが運営されるとなると、もう募集しているのかとか、そういうところも分からなかったので、答えられる範囲で、分かる範囲でお答えいただければ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-006"},{"speaker":"田中委員","kind":"確認","question":"ですので、品川区としてまだ結論が出ていないということですけれども、ぜひ現金の方向に進んでいってほしいと思うのですけれども、そこについての見解と、またコールセンターや郵送料なども、２段階にしてしまうとその分、経費がかかってしまうということがあるので、一括で済むような方向を検討されたのかという、多分、今回の補正が通ってしまえば分かれてしまうと思うのですけれども。","respondent":"渡辺委員長、黒田財政課長","answer":"前段のことだけ。本件事業と、その先のクーポン券等はまた別の事業となりますので、それを前提に、見込みを踏まえた答弁をお願いします。それで、現在国会で審議されている、いわゆる５万円相当のクーポン給付事業につきましては、現在、予算も含めて国会で議論されている最中ですので、この後いわゆる国庫補助金を使って行う事業ということになれば、当然。","voiceIndex":20,"id":"exchange-007"},{"speaker":"田中委員","kind":"確認","question":"次の国の補正予算の検討状況によってということですけれども、ほかの自治体では、次の補正予算を見込んで、一括で現金給付にする自治体もあります。ですので、区としてぜひそういう検討をしていただきたかったということを聞きたかったのです。よかったら、その辺について、検討されたのかされていないのかだけ確認させてください。","respondent":"黒田財政課長","answer":"繰り返しになりますが、今回の事業は、国で予算措置されているものに対して対応しますので、これは早急に対応する。","voiceIndex":23,"id":"exchange-008"},{"speaker":"渡部委員","kind":"質問・要望","question":"聞かなくてはいけない。ただ、そういう仕組みなのだというのは、少し、マスコミが１０万円を５万円と５万円というので、何といったらいいのですか、騒ぎ過ぎてしまって、本当のところがうまく伝わっていないような気がします。私なども理解が不足しているのだと思うのですけれど、ですから、その前段分の５万円が今回支給になるということが明確に分かるような体制を取っていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほどからお話がありますが、今、品川区も区政として忙しいときで、３回目のワクチン接種の対応に追われているさなか、ここでまた、クーポン云々ということを進める話ですが、１６億円というお金、どうなるかは国の裁断によりますが、私は、品川区で１０万円、先に出してしまって、補正をまたやらないといけないですけれども出してしまって、その後、全国の自治体も要望しているのですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-010"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"そっちはそっちでしっかり手当てするわけですから、それが足りるか足りないかという議論はあるけれども、低所得の方、また収入が減った方は、引き続き拡充して、いろいろな給付金が出たり、国としてやっているわけですから、それが、これだけ取り上げていろいろな言われ方をして、結果的にこういう形で二分割となってしまったということが、いい、悪いというのはいろいろご意見があったけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2218#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":8444,"voices":45}},{"id":"r03-20211209-10","meetingId":"r03-cm12","date":"2021年12月9日","dateIso":"2021-12-09","committee":"議会運営委員会","time":"午後 １時４５分～午後 １時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5436#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":925,"voices":8}},{"id":"r03-20211223-7","meetingId":"r03-cm12","date":"2021年12月23日","dateIso":"2021-12-23","committee":"厚生委員会","time":"午後 １時０７分～午後 １時５５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第８９号議案、令和３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第８９号議案、令和３年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"コロナによって様々な困難に直面した方々にということで、今回は住民税非課税世帯等が対象で給付金が出されるということですけれども、ご説明いただいたところでお聞きしたいのですが、家計急変世帯というのは、令和３年１月以降、非課税世帯並みの収入になった世帯ということで、それで、特定の月という説明があったのですけれども、そうすると。","respondent":"櫻木生活福祉課長","answer":"おおむねご指摘のとおりでございまして、正確に申し上げると、非課税世帯相当であるということを申告していただく際に、１か月分の収入の書類のご提出をもって、それを１２倍したところで非課税相当かどうかを判定するということになりますので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、自分が非課税世帯並みの収入になってしまったなと、ぱっと分かる人はそんなに多くないのではないかなと思うのですけれども、分かりやすい資料というか、そうしたものを区としては出していただけるのか。それが周知されるのは大変なことかなと思うのですけれども、要は、対象なのにもらえない人が生まれないために、どういう工夫がされるのかなというのをお聞きしたいと思います。","respondent":"櫻木生活福祉課長","answer":"周知につきましては、ポスター等の掲示と様々周知していくとともに、委員ご指摘のとおり、ご自身で非課税相当かどうか分からない方は多くいらっしゃると思いますので、ぜひコールセンターにお電話していただいて、いろいろご相談していただければ。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"自分がそうかなと思わなければ問合せもしないので、そこら辺をもうちょっと丁寧にやっていただかないと、せっかくの助けになる給付金が届かないことになると思うので、そこはもうちょっと工夫できないものかなと思うのですけれども、ポスターとか広報とか、ほかにはどういったことを。今後もっと工夫していただきたいと思うのですけれども、いかがですか。","respondent":"櫻木生活福祉課長","answer":"その際には、当然ながら周知等も含めて、届くような形で進められればと考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"とにかく対象なのにもらえない方が出ないようにというのは強く求めておきたいなと思うのですけれども、あと、家計急変世帯が４,０００世帯ということで、さっき、これよりは少なくなる見込みという説明があったかなと思うのですが、この家計急変世帯数というのは、何を根拠に出された数なのでしょうか。","respondent":"櫻木生活福祉課長","answer":"こちらの数字につきましては、都のほうから、家計急変世帯数の予算や様々な施策の検討に当たっての目安として、非課税世帯数の７％程度という数値が示されておりますので、それに基づいて推計したものです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、東京都が出してきたいろいろな中から出されてきたということですけれども、これがもし４,０００世帯を超える場合の対応はどうなるのですか。４,０００世帯で終わりではなく、そこは対応していただけるということになるのでしょうか。","respondent":"櫻木生活福祉課長","answer":"こちらにつきましては、予算が足りなくなったということであれば、国の補助等の関係もありますが、基本的には補正予算を新たにお願いして措置していくという形になるのかなと考えております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。それで、申請書等々、返送先や申請先というのは生活福祉課のところでとありますけれども、申請書はダウンロードできるものになっていますでしょうか。","respondent":"櫻木生活福祉課長","answer":"実は申請書の正式な様式等は、国のほうからまだ確認できない状況ではあるのですが、これまでの経緯を見ますと、ダウンロードできるような形でご提供できればと考えています。","voiceIndex":15,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"確認","question":"それが非課税世帯数の５万６,５９７世帯の中に含まれているものだろうと思うのですけれども、そこの確認と、そうすると、生活保護の基準ラインで見ると対象になるとか、そういう分かりやすいものでもないのですか。生活保護の基準で見るものではないのでしょうか。伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"２点目のお尋ねとしましては、こちら、非課税の区分と生活保護基準を満たすかどうかというのは全然別の基準でございまして、非課税世帯につきましては、いわゆる課税の基準に則って、扶養人数が何人とか、そういう形で計算されるものです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"確認","question":"私たちもこういう給付金が始まりますよというのでご説明するときに、どういう人が対象なのかと言われたときに、すごく説明しづらいなと感じるのです。それで、支給されるのは、資料のスケジュールのところで、２月中に非課税世帯へ確認書を送付されて受付開始となっていて、２月下旬に家計急変世帯の受付を開始するということですけれども、受付次第、給付は順々に進んでいくということでいいですか。","respondent":"櫻木生活福祉課長","answer":"私どもの目標感としては、そのような形で着金ができるように努力してまいりたいと考えています。","voiceIndex":19,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それなので、今年１月から１２月までの収入が、来年は非課税になりそうだと、来年の課税のところで非課税になりそうだという方々が対象だということで基本的に考えていいでしょうかということと、それから、１か月分だけでも非課税ということであれば認められるということであれば、来年非課税にはならないけれども、それを１２で割ったのが１か月でもあれば対象になると。","respondent":"櫻木生活福祉課長","answer":"基本的に家計急変世帯のルールとしましては、令和３年１月以降令和４年９月までの任意の１か月の収入をもって経済状況を推定することになっております。もう少し詳しく申し上げると、収入の種類は、給与、事業、不動産、年金という形で限定された形で列挙されております。","voiceIndex":22,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"出していただいたほうがみんなが分かる、そういうふうに言われて初めてそうなのかとイメージできるので、そういうものはぜひ出していただきたいと思うのですけれども、その点、伺いたいと思います。それと、生活保護は、今回の１０万円というのはもちろん収入とみなされないということで確認させていただきたいと思いますので、その点についても伺います。","respondent":"櫻木生活福祉課長","answer":"周知を分かりやすくということでございまして、もちろん私どもも分かりやすいチラシを作りたいとは思っています。ただ、税法になるので、どこまで細かく書けるかみたいなところもありますので、イメージがつきやすいような形で作れればと考えています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"もう１つ、家計急変世帯相談受付開始というのがありますけれども、これは相談をしてから受け付けるということになっていくのか、それとも、自分は対象になるなと思ったら、ホームページからダウンロードして郵送という形でしてもいいのか、その点についても伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"ちょっと相談しながら何が必要かみたいなお話が必要であれば、相談窓口でお話しいただければと考えています。","voiceIndex":26,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"何点か。これに１２を掛けると１００万円になる。逆算すると。これに１２を掛けると１５６万円になるというようなところの分かりやすい周知というのですか、お知らせをしていただきたいなと思うのですが、今の数字は私が勝手にくくった数字なので、正確性も含めて、また周知についてのお考えをお聞きしておきたいと思います。細かい点も含めて、大事な点を何点かお知らせいただきたいと思います。","respondent":"櫻木生活福祉課長","answer":"それにつきましては、こちらもまだ国のほうから出ていないところです。可能な限り簡素な方法で対応させていただければと考えています。","voiceIndex":29,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"先ほどの議論でも、品川区社会福祉協議会、また、暮らし・しごと応援センターというワードが出てきています。今日の資料の周知方法の中には、手交すると。ここについてはどういうご答弁になるか。分かっている、または想像できる方については、できれば触っていただきたいなというお願いというか、思いがありますので、この点についてご答弁いただければと思います。","respondent":"櫻木生活福祉課長","answer":"過去の品川区社会福祉協議会利用者等について、どういう形で周知していくかという点につきましては、品川区社会福祉協議会とも話をしながら、周知方法については考えていければと考えています。","voiceIndex":31,"id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"これは国の補正予算が通ったのが一昨日とかだと思うのですけれども、迅速に対応してくださいまして、本当にありがとうあります。ほかの委員が質問されていて、ほとんど理解したのですけれども、細かいところを２点ほど。その結果は分からないですけれども、それは先ほどもありましたが、国に対応を聞くのか、そういったところとか、ちょっと細かいのですけれども、教えていただきたいと思います。","respondent":"櫻木生活福祉課長","answer":"２点目、ＤＶにつきましては、ＤＶに限らず、要配慮、配慮が必要な方については個別的な対応を考えておりまして、関係機関と連携しながら、どういう形で申請書等をお渡ししていくかというのは検討してまいりたいと考えています。","voiceIndex":34,"id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"確認","question":"すみません。もし款が違ったら、そう言っていただけるとありがたいのですけれども、対象の方に支給されるのが、来年度の５月に非課税世帯の方は受付終了だから、その後になるわけですね。ごめんなさい。支給される時期が、非課税世帯の方はいつぐらいなのか、家計急変世帯の方はいつぐらいなのかというのをまず確認します。","respondent":"櫻木生活福祉課長","answer":"いずれも、送付して申請書を返送していただく、もしくは申請をお受けしてから事務処理等の手続きが一定期間かかってしまいますが、順次お支払いしていく流れになるかと考えていますので、先ほど申し上げたとおり、２月下旬から３月上旬での着金を目標にして。","voiceIndex":37,"id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問","question":"要するに、年度をまたがないように支給をするという形、でもないですか。それで、出納整理期間の４月１日から５月３１日に支給すればいいですけれども、それを超えたときに、決算をどういうふうにするか分からないので、残したままのものはどういう形になるのでしょうか。今年度の決算がどういうふうになっていくのか。すみません、もし分からなかったらいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ伺います。どうしてかというと、品川区はよく堅いと言われるから、着実にやってくれるのはいいのだけれども、逆に言うと、遅いという話もよくあるじゃないですか。何があっても、よく。この前、千代田区の方と話したら、１月を目指すと。今回だって、１０万円、江戸川区は早いなとかとなるではないですか。品川区がこうやっていったときに、このスケジュールで、遅いと言われないですよねという確認。","respondent":"櫻木生活福祉課長","answer":"ただ、早い区は、お話にありましたとおり、１月下旬にという話も聞いておりますし、２月中、２月下旬という想定の区もあると聞いておりますので、品川区としても着実に、かつ、できるだけ早期に実施できるよう努めてまいりたいと考えています。","voiceIndex":43,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"意見","question":"もちろん着実にというのが一番大切なことなので、それはそのとおりにやってもらいたいのだけれども、ぜひ区民の方から遅いと言われることが我々の耳にあまり入らないように、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"暮らし・しごと応援センターは生活福祉課の管轄ですし、品川区社会福祉協議会もそういうふうにいろいろ連携を取りながらやっていると思いますので、ぜひその２か所のところはこれまでの相談の方にということでお願いしたいと思うのですけれども、改めてよろしいですか。","respondent":"櫻木生活福祉課長","answer":"短期的にはしっかりと、非課税世帯であったり家計急変でご相談にいらっしゃる方が大変多くいらっしゃると思いますので、尽力をしつつ、申請状況等を見ながら、周知方法について適切に考えていきたいと思っています。","voiceIndex":47,"id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"さらに多くの方まで行き渡る給付金であるべきだなと思います。国も先日の臨時国会では、７,７３８億円の過去最大の軍事費等を充てていますし、思いやり予算も増額するという異常な大盤振る舞いもしているわけです。ですので、今こそ、そういったところではなく、コロナで苦しむ国民の暮らしの応援に充てるべきだと思いますし、それを区としても国に求めていただきたいと思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3616#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":13453,"voices":59}},{"id":"r03-20211223-9","meetingId":"r03-cm12","date":"2021年12月23日","dateIso":"2021-12-23","committee":"文教委員会","time":"午後 １時１０分～午後 ２時１２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第８９号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第８９号議案、令和３年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"つる委員","kind":"質問・要望","question":"そうしたときには、既に中学生以下で児童手当の対象となっているというのは把握されているわけですから、１６歳から１８歳も当然、９６０万円以下といいましょうか、基準の額ですけれども、児童手当の本則給付の世帯であることは分かっているわけなので、そうすると。","respondent":"伊東子育て応援課長","answer":"児童手当を受給されている世帯で、兄弟関係で１６歳から１８歳の上の子もいるというところですけれども、今回２８日の支給に際しましては、この方々、兄弟関係がいる場合は、その部分も含めまして支給していくということで作業を進めております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"つる委員","kind":"確認","question":"もしできているのであれば、３,９４０名のうち、何人というのでしょうか、何世帯というのでしょうか、その数字を教えてください。","respondent":"伊東子育て応援課長","answer":"そこで、１６歳から１８歳の部分に関しての数字というところですけれども、今拾っているのが１,７３９名、世帯数でいうと１,６３９世帯ということで、暫定的にというか、速報ということで拾ってみた数字がこれで、今作業中なものですから正確かどうかは置いておきまして。","voiceIndex":7,"id":"exchange-002"},{"speaker":"つる委員","kind":"確認","question":"ありがとうございました。そうすると、引き算なので、２,２０１人、ないし、後でもし世帯が分かればなのですが、１６歳から１８歳ないしそれ以上のお子さんという想定の中で、対象が１６歳から１８歳の来年１月初旬に案内、また、下旬に申請があるであろう人数は２,２０１人。確認で、２,２０１人で、世帯はどのぐらいになるのでしょうか。教えてください。","respondent":"伊東子育て応援課長","answer":"そもそも、最初の計算上には、ここで一括支給する、しないにかかわらず計算しておりましたので、１６歳から１８歳ということで単純に計算していたところですので、今回そこにその部分が入るということは、引かれるという考え方でいいかなと思います。","voiceIndex":9,"id":"exchange-003"},{"speaker":"つる委員","kind":"質問","question":"伺ったのは、純然たる１６歳から１８歳、要するに中学生以下の弟や妹がいる１６歳から１８歳の数字というのが１,７３９名、世帯でいうと１,６３９世帯であろうと頂いて、人数は単純に３,９４０名から引き算すれば、２,２０１人が１６歳から１８歳ないし上の兄や姉がいらっしゃるという数だと思うのですが、引き算の２,２０１人の、世帯では何世帯あるのでしょうか。分かれば教えてください。","respondent":"伊東子育て応援課長","answer":"すみません。今、数字的なものを探し切れておりません。","voiceIndex":13,"id":"exchange-004"},{"speaker":"つる委員","kind":"確認","question":"これは前回の委員会でもあったかどうかなのですが、課税証明書等で確認するというところだと思うのですけれども、改めて、その世帯が対象世帯かどうかという確認をする書類等、何によるのかというところと、大体皆さん困っていらっしゃるわけだから必要とされているわけなので、少しでも早くという前提があると思う中で、そうすると、職員の皆さんのそうした確認作業の処理能力だとか件数、これが今。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-005"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう作業があるわけですよね。そこのタイムラグとかいうところについて、どのぐらいかかるのか。支給のタイミングですね。この辺りが分かれば教えていただきたいと思います。","respondent":"伊東子育て応援課長","answer":"１点目の添付書類に関しましては、基本的には課税証明書ですとか非課税証明書ですとかそういうものと、公務員に関しては、児童手当の支払通知書があるのですけれども、それで本則給付なのか分かるのですが、それがあればつけてもらうことになっています。","voiceIndex":16,"id":"exchange-006"},{"speaker":"つる委員","kind":"質問・要望","question":"どうしていくのか、国の制度ですからしっかり議論していくという一定のことはあるわけですが、一方で、自治体によっては既に、そういう世帯であったとしても、自治体の対応で、本当に給付されるべき方に、世帯に、親子に支給していくというふうに対応している自治体もあるわけです。もしくは、そうでなければ、どういうふうに考えているとかあれば教えてください。","respondent":"伊東子育て応援課長","answer":"区としてどうなのかというところにおきましては、現状、国の示されている制度の中で動いておりますので、今のところ、そこに対しての対応というのは考えていないという状況です。","voiceIndex":18,"id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"ただ、こういう場合についてはまた別の課題としてあるわけですね。ですから、この辺りは他の自治体の取組、品川区であれば２３区ですとかそうしたところのやり方があれば見ていただいて、確実に子どもに今回の給付金、そしてメッセージがしっかりと届くような給付の体制は、これは別で取っていただきたいと思うのですが、改めてご答弁いただければと思います。","respondent":"伊東子育て応援課長","answer":"それぞれ、明石市に限らず、ほかの自治体でも何かしら別の手だてをして救済していくという動きがあるところもあるかと思いますけれども、現時点で品川区としては、国が決めた範囲の中での給付ということで進めていくです。","voiceIndex":20,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"先に聞けばよかったのですが、繰り返しですけれども、そこについてはいろいろな工夫で、例えば今お子さんを養育していない側に給付金があったとしても子どもに届くような、どういう投げかけが行政としてできるのか分かりませんけれども、できる限りの支援といいましょうか、そこは手だてを取っていただきたいなと。これは要望します。","respondent":"伊東子育て応援課長","answer":"すみません。離婚している数につきましては、調べておりません。","voiceIndex":22,"id":"exchange-009"},{"speaker":"松本委員","kind":"確認","question":"今の点なのですけれども、離婚もあるのですが、多分普通に調停とかやっていると、離婚の前に別居というのがありますよね。児童手当のスキームで考えたら、まず、９月３０日以降１２月２３日までの間に別居を理由として児童手当の振込口座を変えている、そういう世帯があるかどうか、そこを確認したいと思います。","respondent":"伊東子育て応援課長","answer":"児童手当制度の中の口座変更ですとか様々な変更というのは、その都度、ご本人の状況に応じて申請されていると認識しております。","voiceIndex":25,"id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"この９月３０日の基準日というのは、これは国が示したものなのでしょうか。お願いします。","respondent":"伊東子育て応援課長","answer":"国のほうで基準日を設けて、その時点で、簡単に言うと、住所要件的にはどっちに行くかというところで、その市区町村で給付するというのが前提です。","voiceIndex":27,"id":"exchange-011"},{"speaker":"松本委員","kind":"質問","question":"だって、今、現実に児童手当を振り込んでいるところになるわけですから、それをやるべきだと多分一般的にもみんな思うと思うのですけれども、それができないのは、それをやってしまうと、国から今回の国庫支出金が出ないという話なのでしょうか。国政がおかしいということになると思うのですけれども、出るのであれば、やはりやったほうがいいと。","respondent":"伊東子育て応援課長","answer":"対象児童なのかどうかというところでのいろいろな基準日だったり所得だったりということでは、それは児童手当制度の中でということでは決められております。単純に言えば、プラスアルファで何か出しますよとか、そういう部分に関しては見ませんよというような話です。","voiceIndex":29,"id":"exchange-012"},{"speaker":"松本委員","kind":"質問","question":"であれば、少なくとも１０月以降に切り替えている世帯については、ぎりぎり、基準日をもっと遅らせるとかやりようがあると思うのですけれども、手続が必要とかではなく、切り替えている世帯については切替え後のほうに振り込むべきだと思うのですが、そこのご見解はいかがでしょうか。","respondent":"伊東子育て応援課長","answer":"口座情報だけに関して言えば、変更後の口座ということになります。","voiceIndex":31,"id":"exchange-013"},{"speaker":"松本委員","kind":"質問・要望","question":"ご答弁いただきたいのだけれども、基準日というのはあくまで住民票だけで、１０月になって口座を切り替えた人たちのところには、切替え後の口座にお金が入るということでよろしいでしょうか。確認いたします。","respondent":"伊東子育て応援課長","answer":"そのとおりです。","voiceIndex":33,"id":"exchange-014"},{"speaker":"松本委員","kind":"質問・要望","question":"分かりました。申し訳ありません。ここについては、先ほどのつる委員のご指摘のとおりだと思うので、ここは重複するので、これは要望して、こちらももっと早くできればと思っています。最終的には２０日のタイミングで決定が出ているかと思うのですけれども、そこの流れのところ、どういう流れでこの意思決定が行われたのか伺います。","respondent":"伊東子育て応援課長","answer":"１５日ですけれども、実質的には１６日に目に触れたというところではありますが、その後、どうしようかということで、企画部門を交えまして内部的な検討を進めてきたところです。その流れで、現金化のところをまず決定しようということで思いつきました。","voiceIndex":35,"id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"現金で分割でというふうにまずは可能そうだというのが分かったタイミングと、最終的には多分２０日の段階で一括だというふうになったと思うのですけれども、恐らく１６日に把握されて、２０日までの５日の間に、どのタイミングで現金で一括でいこうということが内部的にほぼ決まったのか。そこの部分はどのタイミングなのでしょうか。","respondent":"伊東子育て応援課長","answer":"技術的に、現金に決めたというところで、でも現金だったらなるべく早いほうがいいだろうという話というか、そういう意見も入っていたところですので、それに対してどうできるかというところで、最初はスケジュール的に年明けかなという話を打合せの中ではしていたのですけれども。","voiceIndex":37,"id":"exchange-016"},{"speaker":"松本委員","kind":"確認","question":"今回の１６日から２０日の流れの中で、区長がこうするべきではなかろうかという意見を述べたことというのはあるのでしょうか。","respondent":"伊東子育て応援課長","answer":"私が直接ということではございませんけれども、その都度、企画部門から報告といいますか、意見を仰いでいると認識しております。","voiceIndex":39,"id":"exchange-017"},{"speaker":"松本委員","kind":"質問","question":"ここはやはりしっかりと、行政側が報告して動いたのか、それとも区長がきちんとリーダーシップを取ったのかというのは大事だと思うので、明確にしたいのですけれども、区長から年内現金一括給付でという意見は出たのでしょうか。","respondent":"柏原子ども未来部長","answer":"一括で１０万円でいく場合は、そのときにはそれを省いてもいいというようなコメントが急に変わって出てきたというのがありました。それは今まで我々の認識にはなかったところなので、それであれば、他の自治体もそれで動けそうだというのが見えてきました。","voiceIndex":41,"id":"exchange-018"},{"speaker":"松本委員","kind":"確認","question":"そうすると、前回の補正だと６５７万１,０００円が郵送料等で計上されていて、今回も一定額計上されているということで、ここは、当初の計画から変わってしまったから追加で郵送料がかかるようになってしまった部分も、部分もあると言っているのは、１６歳から１８歳の部分が前回の補正予算では入っていなかったので、改めて今回、１６歳から１８歳の部分とは別に郵送する必要があったのかなかったのか。","respondent":"伊東子育て応援課長","answer":"郵送に関しましては、最初の段階、１３日ですけれども、最初の５万円支給しますという通知は出しているところです。今回この議決が通りましたらば、今度、１０万円で支給しますという通知は出します。ということで、その部分は必要というところになります。","voiceIndex":43,"id":"exchange-019"},{"speaker":"松本委員","kind":"確認","question":"加えて確認なのですけれども、今回の補正予算説明書の事項別明細書を確認すると、システム改修費等になっているのです。前回の場合だとこのシステム改修費等はなくて、コールセンター運営等委託のほうが計上されていたのですけれども、今回のシステム改修費等の「等」に何が含まれるのか、お願いいたします。","respondent":"伊東子育て応援課長","answer":"システム改修費と、いわゆる消耗品関係と……、そうですね。消耗品関係……、役務費は別立てですので、一般事務費と委託料ということです。","voiceIndex":45,"id":"exchange-020"},{"speaker":"松本委員","kind":"質問","question":"コールセンターのところは、追加ではかからなかったという理解でよろしいのでしょうか。","respondent":"伊東子育て応援課長","answer":"コールセンターに関しましては、前回の補正の中での資金で、その中での手当てということになります。","voiceIndex":47,"id":"exchange-021"},{"speaker":"松本委員","kind":"確認","question":"すみません。細かくいろいろ聞きました。確認が取れましたので、この年末の中で皆さん本当に大変な作業だったと思います。厳しい追及になったことをおわびしつつ、いろいろと問題はあると思いますので、引き続きどうかよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-022"},{"speaker":"つる委員","kind":"確認","question":"今、松本委員のところで確認をしていただいた部分があるのですが、先ほど私の最後の質問の部分なのですけれども、ひとり親ないしＤＶ、要するに今現在別居状態になっている、その辺りの対応のことに関連してなのですが、先ほど松本委員のところでは、１０月に入ってから口座変更等がある場合とかとあって、ご答弁の中ではそこに支給というご答弁であって、それも今回の予算が通った。","respondent":"伊東子育て応援課長","answer":"それで、はみ出すというか、別の形、追加給付も含めてなのですけれども、いろいろな別の形でやるところに関しては、ここの部分の補助としては出さないけれども、独自財源なり、今おっしゃったような財源を使っていいというような話だったのかなと思っているところです。","voiceIndex":50,"id":"exchange-023"},{"speaker":"つる委員","kind":"確認","question":"いろいろな、現在進行形でそれぞれが、国も自治体もある中での対応という形になっているのだと思うのですが、繰り返しですけれども、やはり大切なことは、今も含む未来を託すべき子どもたちにしっかりと応援のメッセージが伝わるこの１０万円がきちんと届くということになることが一番大切なことだと思いますので、やり方、手段、方法はいろいろあるにしても、結果としてそういうふうになるような形を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-024"},{"speaker":"吉田委員","kind":"確認","question":"質疑の中でいろいろ確認できたのですけれども、どうしても私たちが気になっているのは、先ほどの議論の中にも出てきましたが、もちろん離婚係争中の方とか別居状態の方ということもあれでしたけれども、やはりこういう制度に一番アクセスしにくいのは、身を潜めてＤＶから逃げている方たちなのです。今も制度というか、あるのだと思うのですけれども、改めて伺いたいのですが、いかがでしょう。","respondent":"伊東子育て応援課長","answer":"ＤＶに関しては、この間、様々な給付金とかの中でも、一定程度配慮するようにということで、我々のほうにもそういう通知が来るのと、あと、ＤＶ関連の相談機関のほうにも来ているところですので、そういうところで、相談があればそういう話をして、こちらにつながるというか。","voiceIndex":54,"id":"exchange-025"},{"speaker":"吉田委員","kind":"確認","question":"区としてのＤＶの相談窓口というのは、男女共同参画センターのほうだと何度も確認はしているのですけれども、そこと子育て応援課、だから、二度相談しないとうまく制度にアクセスできないというのが品川区の、どうしてもそれはしようがないものなのかもしれないのですが、男女共同参画センターのほうはＤＶのご相談があると、必ずこちらにもう一回相談してくださいねといって。","respondent":"伊東子育て応援課長","answer":"ですので、そこが入り口になって、つながるという形になろうかと思います。","voiceIndex":56,"id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"なかなかＤＶの被害者、この状況がすごくセンシティブな問題なので、そこを区が何とか制度につなげようというのが難しいのは本当に承知して、それでもなおかつ、何とかならないかなと思って意見を申し上げておりますが、そういう状況、特にこういう具体的な給付金というのがあったときには、ぜひ直接の相談窓口に、こういう制度のことがありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-027"},{"speaker":"松澤委員","kind":"質問・要望","question":"１６歳から１８歳、先ほどの話を聞いていますと、３週間ぐらいいろいろな手続があるというお話もありましたけれども、なるべく早くお願いしたいという要望とともに、先ほどつる委員も含めて皆さんおっしゃっていましたが、離婚であるとかＤＶである、別居である、そういったところの中で、やはりその後の工夫というのは、私も聞いていて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-028"},{"speaker":"つる委員","kind":"質問・要望","question":"賛成します。意見は、先ほど質疑させていただいて確認させていただきました。現金一括給付、年内に可能となったというところを含めて、歓迎するものであります。それから、離婚された世帯の子どもに対する給付の在り方についても、先ほど質疑させていただいたとおりで、本当にきめの細かい、積極的な対応を、他自治体のいい事例を参考にしていただいて、ぜひ品川区らしい工夫をやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に、コロナで苦しむ人たちへの支援という給付金のもともとの趣旨から見れば、やはり対象がまだ狭いというのは事実だと思いますので、今回、補正予算がこういうことで組まれましたけれども、子ども未来部が所管していて、また、実際に支援事業を行っている、学生ですとか若者への支援も併せて行うべきだと思っておりまして、困窮する大学生を抱える世帯あるいは若者単身世帯。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-030"},{"speaker":"吉田委員","kind":"意見","question":"ただ、一番気になっているのが、先ほども言いましたが、いろいろな制度にアクセスしにくい方たち、本当に身を潜めておびえながら暮らしている方たちにもきちんと、そういう方たちこそ必要なお金だと思いますので、区として難しい点があることは重々承知ですが、広報とか、それから相談窓口への周知も含めて、適正に子育て世帯に渡るような制度にしていただくことを前提として、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-031"},{"speaker":"松本委員","kind":"質問・要望","question":"ちょっと意見ですけれども、今日いろいろ確認させていただいて、やはり一番のポイントだったのは、児童手当の口座の基準日、これが私のほうでも、報道等では８月末を基準にということが出ていましたので、そうなると、９・１０・１１・１２月と、そこで口座を切り替えていて既に児童手当をもらっている世帯が、１０万円振り込まれないとなると、これは大ごとだということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5054#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":19460,"voices":68}},{"id":"r03-20211223-5","meetingId":"r03-cm12","date":"2021年12月23日","dateIso":"2021-12-23","committee":"総務委員会","time":"午後 ２時２０分～午後 ２時４７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"説明に入る前に、所管委員会における審査結果","agenda":"説明に入る前に、所管委員会における審査結果","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"今回予算が通れば、１０万円全額現金で給付されるということになるので、前回の総務委員会でも、私自身、１０万円全額現金給付ということは求めたことなので、非常に歓迎したいです。そのときにも申し上げたのですけれど、依然として狭過ぎるという点に関して、区の認識およびお考えをいま一度お伺いしておきたいと思います。身近な例で申し上げれば、これは経営している方ではないですけれども……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"特に狭いという面でも、営業・事業面への支援がないというところが一つの特徴だろうと思います。特にこの辺りの認識、お考えをお伺いしたいと思います。","respondent":"黒田財政課長","answer":"事業者への支援につきましても、今回の国の補正予算の中でも様々施策が考えられております。区のほうではこれから当初予算の編成もありますし、今年度の当初予算でありますとか補正予算の中でも取り組んでまいっておりますので、区は区として取り組んでまいりたいと考えています。","voiceIndex":10,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"でも、おっしゃいましたように、これから予算を組む場面ですし、また、補正予算という形で区独自の１０万円の給付や３万円の給付をやったりしたこともあるわけですし、あるいは上乗せで家賃支援給付金なんかもやったことがあります。そういうふうに区独自の姿勢も示すことができるわけですから、私としてはそういうこともできるのだということを前提に、いろいろ考えていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"これから品川区は３回目の接種に対して動かなければいけない。この多忙の中で、本当に助かったかなと思います。そうすると、９月１日以降に離婚したりで非親権者となった親に給付されたり、親権者となったもう一方の親が受けられないという事態も発生するのではないかと思うのですが、その辺、どうなのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"特に私が心配しているのは若者世代への周知なのですが、やはり情報を取りにくい、区のホームページなどを検索しようとか、なかなか思い浮かばない若い世代の人たちへの情報提供はすごく必要だなと考えていて、そこら辺の考え方、また、先ほどもありましたが、ＤＶ等で今避難されている方たちへの周知、子育て応援費のほうも生活保護費のほうも周知がとても重要だと思うので。","respondent":"黒田財政課長","answer":"１点目の契約の件ですが、これは本日、補正予算をご審議いただいておりますので、成立した後に早急に事務に取りかかれるようにというところで、所管のほうで見積りを取った事業者はあると思いますが、まずはどのようにすれば早く事務が進められるかという観点で。","voiceIndex":18,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"お手洗いだったりを借りに来るというか。なので、図書館だったり公園とか、そういうところでもこういった給付が始まりますといった周知を、ぜひ目につくところでしていただきたいなということを要望したいのですが、いかがでしょうか。契約のところについてですけれども、ごめんなさい、何契約、随意契約だったりとかという、そこだけを知りたいのですが、教えていただけますでしょうか。","respondent":"黒田財政課長","answer":"契約は、すみません、まだ予算が成立しておりませんので、今後、予算成立後に事務を行いますので、どういった契約にするかということについては、所管で検討していると思いますが、現時点で私からはお答えできないです。","voiceIndex":20,"id":"exchange-006"},{"speaker":"渡部委員","kind":"質問・要望","question":"確認させていただきたい点が、人事のほうは、ある程度給付が落ち着くまでの時限で、なおかつ兼任でやっていくのでしょうか。今やっておけば、詳細が出てきたらすぐ動けるので、これは実際まだほとんどが何も分からない、質問はしませんけれども、特に家計急変世帯の４,０００世帯なんていうのは、これはどうやって決めるのと。だから、聞きたいのは２点です。人事のところと。","respondent":"佐藤（憲）企画調整課長","answer":"先ほどご紹介したとおり、組織も設置しておりますので、そちらに関しては、全庁体制で、係長なり、異動といいますか、そういった形も今後進めていかなければならないと考えております。","voiceIndex":23,"id":"exchange-007"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"１６歳から１８歳についても、児童手当をもらっているお子さんが下にいる場合は、一括で年内に振り込んでいただけるということも確認していますので、そういう方にとっては、２人いれば２０万円ぐらい年内に出るということで、やはり年を越すのと年内に出るというのは大分違ってきますので、また、それ以外の単独の１６歳から１８歳についても、年明け早々。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"賛成しますが、意見を言わせてください。ホームページや暮らし・しごと応援センターなどの担当窓口に対象の方が行かなければ分からないという周知ではなくて、対象者の方が気づくことのできる徹底した周知、本当に困っている方に届くような周知をお願いしたいと要望しまして、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2220#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":9134,"voices":44}},{"id":"r03-20211223-10","meetingId":"r03-cm12","date":"2021年12月23日","dateIso":"2021-12-23","committee":"議会運営委員会","time":"午後 ３時４０分～午後 ３時４１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5440#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":902,"voices":8}}]);
